C({id:1,t:"Anatomia e funzioni della cute",sub:"Epidermide, derma, annessi",
topics:[
["Struttura e origine",["Cute = epidermide + derma + ipoderma + annessi (unità pilo-sebacea, ghiandole sudoripare, unghie).","Ectoderma: cheratinociti, melanociti, cellule di Merkel, annessi, fibre nervose (da qui le malattie neuroectodermiche come neurofibromatosi e sclerosi tuberosa).","Mesoderma: derma, ipoderma, vasi, cellule di Langerhans (secondo le dispense).","Linee di Langer: direzione delle fibre del derma, guidano le incisioni chirurgiche; linee di Blaschko: linee di migrazione embrionale seguite da nevi e dermatosi a mosaico."],"ECTO = ciò che vedi in superficie (cheratinociti, melanociti, annessi); MESO = il sostegno (derma, ipoderma, vasi)."],
["Epidermide e cheratinizzazione",["Epitelio pavimentoso pluristratificato cheratinizzato, non vascolarizzato.","Strati dal basso: basale (unico con mitosi, emidesmosomi), spinoso (desmosomi), granuloso (granuli di cheratoialina), lucido (palmo-pianta), corneo (corneociti senza nucleo).","Persistenza dei nuclei nel corneo = paracheratosi (tipica della psoriasi).","Desmogleine dei desmosomi: DSG1 superficiale, DSG3 profonda → bersagli del pemfigo.","Turnover dallo strato basale al corneo: circa 28-30 giorni; nella psoriasi 3-4 giorni.","Lipidi intercellulari (ceramidi) = cemento della barriera: ridotti nella xerosi e nella dermatite atopica."],"Strati: “Bella Signora Garbata Lucida Cornuta” → Basale, Spinoso, Granuloso, Lucido, Corneo."],
["Giunzione dermo-epidermica e derma",["La GDE ancora l’epidermide al derma: emidesmosomi, lamina lucida, lamina densa, fibrille di ancoraggio (collagene VII).","Bersaglio delle malattie bollose subepidermiche (pemfigoide: BP180/BP230; epidermolisi bollosa acquisita: collagene VII).","Derma papillare (lasso, capillari) e reticolare (denso, collagene ed elastina), con fibroblasti, mastociti, vasi e nervi.","Vascolarizzazione su due plessi orizzontali (superficiale e profondo); l’epidermide si nutre per diffusione."],"Bolla SOPRA la GDE = pemfigo (intraepidermica); bolla SOTTO = pemfigoide (subepidermica)."],
["Annessi e funzioni",["Ciclo follicolare: anagen (crescita), catagen (involuzione), telogen (riposo); attività ciclica e asincrona.","Ghiandola sebacea: secrezione olocrina, sotto controllo androgenico (ruolo nell’acne).","Sudoripare eccrine (termoregolazione, ovunque) e apocrine (ascelle, inguine, sbocco nel follicolo).","Funzioni della cute: barriera, termoregolazione, protezione UV (melanina), immunità (Langerhans), sensibilità, sintesi di vitamina D.","Assorbimento percutaneo: aumenta con occlusione, cute sottile (volto, pieghe, genitali), cute lesa, bambini e anziani."],"Ciclo del pelo: Anagen = Attivo, Catagen = Cala, Telogen = Termina."]
],
fc:[["Unico strato epidermico con mitosi?","Lo strato basale."],["Turnover epidermico normale?","Circa 28-30 giorni (3-4 giorni nella psoriasi)."],["Cos’è la paracheratosi?","Persistenza dei nuclei nello strato corneo."],["Bersaglio del pemfigo volgare?","Desmogleina 3."],["Fasi del ciclo follicolare?","Anagen, catagen, telogen."]],
mcq:[["Lo strato con granuli di cheratoialina è:",["Basale","Spinoso","Granuloso","Corneo"],2,"Ne prende il nome."],["Le linee di Blaschko rappresentano:",["Fibre di collagene","Linee di migrazione embrionale","Dermatomeri","Vasi linfatici"],1,"Seguite da nevi e dermatosi a mosaico."],["La ghiandola sebacea ha secrezione:",["Eccrina","Apocrina","Olocrina","Endocrina"],2,"L’intera cellula diventa secreto."],["L’assorbimento percutaneo dei farmaci è massimo:",["Sulla pianta del piede","Sulle palpebre e nelle pieghe","Sul dorso","È uguale ovunque"],1,"Cute sottile."],["Il collagene VII forma:",["Desmosomi","Fibrille di ancoraggio","Granuli","Membrane mitocondriali"],1,"Bersaglio dell’epidermolisi bollosa acquisita."]],
gap:[["Nel soggetto sano il turnover epidermico dura circa ___ giorni.","28",["28-30","30"]],["La fase di crescita del pelo si chiama ___.","anagen",[]],["La desmogleina ___ è localizzata negli strati superficiali.","1",["uno"]]],
match:[["Basale","Mitosi"],["Granuloso","Cheratoialina"],["Corneo","Senza nucleo"],["Langer","Incisioni"],["Sebacea","Olocrina"]],
open:[["Descrivi gli strati dell’epidermide.","Basale (cellule staminali, mitosi, emidesmosomi), spinoso (desmosomi), granuloso (cheratoialina), lucido (solo palmo e pianta), corneo (corneociti anucleati con lipidi intercellulari). Il passaggio richiede circa 28-30 giorni.",["basale","spinoso","granuloso","lucido","corneo","28"]],["Quali sono le funzioni della cute?","Barriera fisica e chimica, protezione dagli UV, termoregolazione, difesa immunitaria, sensibilità, sintesi della vitamina D, funzione estetica e relazionale.",["barriera","UV","termoregol","immun","vitamina D"]]],
recap:["Cute = epidermide, derma, ipoderma, annessi.","Basale, spinoso, granuloso, lucido, corneo.","Turnover 28-30 giorni (psoriasi 3-4).","DSG1 superficiale, DSG3 profonda.","Ciclo del pelo: anagen, catagen, telogen."]});

C({id:2,t:"Lesioni elementari e segni",sub:"Semeiotica dermatologica",
topics:[
["Lesioni elementari primarie",["Macchia: variazione di colore senza rilievo (melanica, vascolare, da pigmenti esogeni).","Eritema: arrossamento da vasodilatazione che scompare alla vitropressione.","Porpora: stravaso di sangue che NON scompare alla vitropressione.","Pomfo: rilievo edematoso fugace (<24 ore), tipico dell’orticaria.","Papula: rilievo solido <1 cm, si risolve senza cicatrice; nodulo: lesione solida più profonda e voluminosa.","Vescicola (<5 mm) e bolla (>5 mm) a contenuto liquido; pustola a contenuto purulento."],"Vitropressione: se SCOMPARE = eritema (vasodilatazione); se RESTA = porpora (sangue fuori dai vasi)."],
["Lesioni secondarie",["Squama: lamelle cornee che si staccano (furfuracee, lamellari).","Crosta: essudato rappreso (sieroso, ematico, purulento).","Erosione/abrasione: perdita di sostanza epidermica, guarisce senza cicatrice.","Ulcerazione: perdita di sostanza che raggiunge il derma, guarisce con cicatrice.","Ragade: fessura lineare in zone di flessione; escoriazione: da grattamento.","Cicatrice, sclerosi (indurimento), atrofia (assottigliamento), necrosi, lichenificazione."],"Erosione = solo epidermide, niente cicatrice; ulcera = derma, cicatrice."],
["Lesioni patognomoniche",["Lesioni che da sole permettono la diagnosi.","Cunicolo della scabbia: rilievo lineare serpiginoso con eminenza acarica a un’estremità.","Tragitto della larva migrans: linea serpiginosa eritematosa che avanza giorno dopo giorno.","Comedone: lesione patognomonica dell’acne."],"Linea serpiginosa: corta con eminenza = scabbia; lunga che cammina = larva migrans."],
["Segni e fenomeni da evocare",["Fenomeno di Koebner (isomorfismo reattivo): nuove lesioni sulle zone di trauma (psoriasi, lichen planus, vitiligine).","Segno di Auspitz: rugiada sanguinante dopo il grattamento della placca psoriasica (papille con capillari dilatati).","Segno della candela: la squama psoriasica si stacca come cera grattata.","Dermografismo: pomfo lineare dopo lo strisciamento della cute (orticaria).","Segno di Darier: strofinando una lesione di mastocitosi compare un pomfo.","Segno di Nikolsky: la cute apparentemente sana si scolla con la pressione laterale (pemfigo).","Lampada di Wood: fluorescenza utile in vitiligine e alcune micosi."],"Psoriasi: CANDELA → membrana → AUSPITZ (gratta e trovi la rugiada)."]
],
fc:[["Cosa distingue eritema e porpora?","L’eritema scompare alla vitropressione, la porpora no."],["Durata tipica del pomfo?","Meno di 24 ore, è fugace."],["Cos’è il fenomeno di Koebner?","Comparsa di lesioni nelle sedi di trauma."],["Segno di Auspitz?","Sanguinamento puntiforme dopo rimozione della squama psoriasica."],["Lesione patognomonica della scabbia?","Il cunicolo con eminenza acarica."]],
mcq:[["Lesione liquida di 8 mm:",["Vescicola","Bolla","Pomfo","Papula"],1,"Sopra i 5 mm."],["Il segno di Nikolsky positivo suggerisce:",["Psoriasi","Pemfigo","Orticaria","Tinea"],1,"Scollamento epidermico."],["Il segno di Darier si ricerca nella:",["Mastocitosi","Psoriasi","Scabbia","Rosacea"],0,"Pomfo dopo strofinamento."],["Quale lesione guarisce con cicatrice?",["Erosione","Ulcerazione","Escoriazione superficiale","Eritema"],1,"Raggiunge il derma."],["Il dermografismo è tipico di:",["Orticaria","Vitiligine","Melanoma","Acne"],0,"Iperreattività cutanea."]],
gap:[["Il comedone è la lesione patognomonica dell’___.","acne",[]],["La vescicola misura meno di ___ mm.","5",["cinque"]],["L’isomorfismo reattivo è detto fenomeno di ___.","Koebner",["Köbner"]]],
match:[["Pomfo","Orticaria"],["Cunicolo","Scabbia"],["Auspitz","Psoriasi"],["Nikolsky","Pemfigo"],["Darier","Mastocitosi"]],
open:[["Distingui le lesioni elementari primarie da quelle secondarie con esempi.","Primarie: compaiono su cute sana, come macchia, eritema, pomfo, papula, nodulo, vescicola, bolla, pustola. Secondarie: derivano dall’evoluzione o dal trauma delle primarie, come squama, crosta, erosione, ulcera, ragade, escoriazione, cicatrice, atrofia.",["primari","macchia","papula","secondari","squama","crosta","ulcer"]],["Quali segni si evocano nella psoriasi?","Segno della candela, membrana di Duncan-Buckley, rugiada sanguinante di Auspitz, fenomeno di Koebner.",["candela","Auspitz","Koebner"]]],
recap:["Vitropressione: eritema scompare, porpora resta.","Vescicola <5 mm, bolla >5 mm.","Erosione senza cicatrice, ulcera con cicatrice.","Patognomoniche: cunicolo, larva migrans, comedone.","Koebner, Auspitz, Nikolsky, Darier, dermografismo."]});

C({id:3,t:"Dermatiti da contatto",sub:"Allergica e irritativa, patch test",
topics:[
["Definizione e istologia",["Dermatosi infiammatoria acuta, subacuta o cronico-recidivante da agenti esogeni chimici, biologici o fisici, professionali o extraprofessionali.","Eczema: istologicamente spongiosi intraepidermica, vasodilatazione e infiltrato perivascolare.","Polimorfismo evolutivo: eritema-edema → vescicole → essudazione → croste → desquamazione → lichenificazione (cronica).","Due tipi: allergica (DAC) e irritativa (DIC)."],"Eczema = SPONGIOSI (l’epidermide diventa una spugna)."],
["Dermatite allergica da contatto",["Ipersensibilità ritardata di tipo IV verso apteni (piccole molecole che diventano antigeniche legandosi a proteine).","Fase afferente di sensibilizzazione: le cellule di Langerhans presentano l’aptene ai linfociti T nei linfonodi.","Fase efferente: un nuovo contatto scatena le lesioni in 24-48 ore.","Coinvolge solo i soggetti sensibilizzati; le lesioni possono estendersi oltre l’area di contatto.","Apteni frequenti: nichel (bigiotteria, fibbie, orologi), cromo (cemento), parafenilendiammina (tinture), profumi, conservanti, gomma."],"DAC = pochi soggetti, serve SENSIBILIZZAZIONE, lesioni che DEBORDANO."],
["Dermatite irritativa da contatto",["Danno diretto, non immunologico, da sostanze irritanti (detergenti, solventi, acqua, acidi, alcali).","Può colpire chiunque, dipende da concentrazione e durata dell’esposizione.","Lesioni limitate all’area di contatto, spesso riproducono la forma dell’oggetto.","Più bruciore che prurito; tipica delle mani di parrucchieri, sanitari, addetti alle pulizie."],"DIC = tutti, nessuna memoria immunitaria, confini NETTI come l’oggetto."],
["Diagnosi e terapia",["Anamnesi lavorativa ed extralavorativa, sede delle lesioni.","Patch test: apteni della serie standard applicati sul dorso per 48 ore, lettura a 48 e 72-96 ore; diagnostico per la DAC.","Il patch test è negativo nella DIC.","Prick test: valuta l’ipersensibilità IgE-mediata (immediata), non la DAC.","Terapia: allontanamento della causa (fondamentale), corticosteroidi topici, emollienti; steroidi sistemici nelle forme estese; protezione (guanti) e possibile cambio di mansione."],"Patch = tipo IV (ritardato, 48-72 h); Prick = IgE (immediato)."]
],
fc:[["Tipo di ipersensibilità nella DAC?","Tipo IV, ritardata, cellulo-mediata."],["Aptene più frequente?","Nichel."],["Lettura del patch test?","A 48 e 72-96 ore."],["Istologia dell’eczema?","Spongiosi intraepidermica."],["Il prick test serve per la DAC?","No: valuta le reazioni IgE-mediate."]],
mcq:[["Lesioni che riproducono esattamente la forma della fibbia, bruciore:",["DAC","DIC","Dermatite atopica","Psoriasi"],1,"Confini netti come l’oggetto."],["Il patch test indaga:",["Ipersensibilità di tipo I","Ipersensibilità di tipo IV","Autoanticorpi","Infezioni"],1,"Allergia da contatto."],["Le cellule che presentano l’aptene sono:",["Melanociti","Cellule di Langerhans","Mastociti","Cellule di Merkel"],1,"Fase di sensibilizzazione."],["Muratore con eczema delle mani: aptene probabile",["Nichel","Cromo","Lattice","Profumi"],1,"Contenuto nel cemento."],["Primo passo terapeutico:",["Antibiotico","Allontanare la causa","Isotretinoina","Biologico"],1,"Senza eliminare l’agente la dermatite recidiva."]],
gap:[["Nella fase efferente le lesioni compaiono dopo ___-48 ore.","24",[]],["L’aspetto cronico ispessito della cute si chiama ___.","lichenificazione",[]],["La tintura per capelli contiene parafenilen___.","diammina",["diamina"]]],
match:[["DAC","Tipo IV"],["DIC","Danno diretto"],["Patch test","48-72 ore"],["Prick test","IgE"],["Cemento","Cromo"]],
open:[["Confronta dermatite allergica e irritativa da contatto.","DAC: immunologica di tipo IV, solo nei sensibilizzati, prurito, lesioni che debordano dall’area di contatto, patch test positivo. DIC: danno tossico diretto, può colpire chiunque in base a dose e durata, bruciore, lesioni limitate all’area e alla forma dell’oggetto, patch test negativo.",["tipo IV","sensibilizz","prurito","diretto","chiunque","patch"]],["Come si esegue e interpreta il patch test?","Si applicano gli apteni della serie standard in camerette occlusive sul dorso per 48 ore, con letture a 48 e 72-96 ore; la positività (eritema, papule, vescicole) indica allergia da contatto, va correlata con la clinica.",["apteni","dorso","48","72","positiv"]]],
recap:["Eczema = spongiosi, polimorfismo evolutivo.","DAC: tipo IV, apteni (nichel), lesioni che debordano.","DIC: irritante diretto, chiunque, confini netti.","Patch test per DAC; prick per IgE.","Terapia: via la causa + steroidi topici."]});

C({id:4,t:"Dermatite atopica",sub:"Eczema atopico, criteri, terapia",
topics:[
["Definizione ed epidemiologia",["Dermatosi infiammatoria costituzionale cronico-recidivante, T-linfocitaria e IgE-mediata, con fasi di remissione e riacutizzazione (flares).","Insorge nei primi mesi o anni di vita; peggiora d’inverno, migliora d’estate (sole).","Associata nel 30-80% ad altre allergopatie: rinocongiuntivite, asma (marcia atopica).","Oggi considerata una malattia sistemica (cute, occhi, mucose, vie respiratorie)."],"Marcia atopica: PELLE → NASO → BRONCHI."],
["Eziopatogenesi",["Predisposizione genetica: mutazioni della filaggrina → barriera cutanea difettosa.","Perdita di acqua transepidermica, xerosi, ingresso di allergeni e irritanti.","Risposta immunitaria Th2 (IL-4, IL-13, IL-31 del prurito), IgE elevate.","Colonizzazione da S. aureus; fattori scatenanti: sudore, lana, stress, detergenti aggressivi."],"Filaggrina rotta = muro senza cemento."],
["Clinica per età",["Lattante: lesioni eritemato-essudative e crostose a guance e volto (risparmio del triangolo naso-bocca), superfici estensorie; crosta lattea.","Infanzia: pieghe di flessione (gomiti, poplitei), polsi, caviglie; lichenificazione.","Adulto: volto, collo, mani, lichenificazione; forme croniche.","Prurito intenso, soprattutto notturno, con circolo vizioso grattamento-prurito.","Complicanze: sovrainfezione da S. aureus, eczema erpetico (Kaposi-Juliusberg) da HSV, molluschi, verruche."],"Bambino piccolo = guance; bambino grande = pieghe."],
["Diagnosi",["Clinica, con criteri maggiori e minori (servono 3 o più criteri).","Maggiori: prurito, morfologia e distribuzione tipiche per età, decorso cronico-recidivante, storia personale o familiare di atopia.","Minori: esordio precoce, IgE totali o specifiche elevate, xerosi, lichenificazione, pieghe di Dennie-Morgan, pitiriasi alba.","Prick test e IgE: indicano sensibilizzazione IgE ma non sono criterio diagnostico per la DA."],"Il prick positivo NON fa diagnosi di dermatite atopica."],
["Terapia",["Base: emollienti ogni giorno per ripristinare la barriera, detergenti delicati, evitare i fattori scatenanti.","Flares: corticosteroidi topici; inibitori della calcineurina topici (tacrolimus, pimecrolimus) per volto e pieghe.","Fototerapia (UVB a banda stretta).","Sistemici nelle forme moderate-gravi: ciclosporina; biologici come dupilumab (primo approvato, anti-IL-4Rα), tralokinumab (anti-IL-13); JAK inibitori (upadacitinib, abrocitinib, baricitinib).","Antistaminici per il prurito notturno; antibiotici se sovrainfezione."],"Emolliente SEMPRE, steroide nelle crisi, DUPILUMAB nelle forme gravi."]
],
fc:[["Proteina della barriera mutata nella DA?","Filaggrina."],["Primo biologico approvato per la DA?","Dupilumab (anti-recettore IL-4α)."],["Sede tipica nel lattante?","Guance e volto, con risparmio del triangolo naso-bocca."],["Cos’è l’eczema erpetico?","Disseminazione di HSV su cute atopica (Kaposi-Juliusberg)."],["Base della terapia?","Emollienti quotidiani."]],
mcq:[["Bambino di 8 anni con eczema delle pieghe dei gomiti:",["Dermatite seborroica","Dermatite atopica","Psoriasi inversa","Tinea"],1,"Distribuzione flessoria tipica."],["Citochina del prurito nella DA:",["IL-17","IL-31","TNF-α","IL-23"],1,"Insieme a IL-4 e IL-13."],["Il prick test positivo nella DA:",["Fa diagnosi","Indica solo sensibilizzazione IgE","È sempre negativo","Sostituisce la clinica"],1,"Non è criterio diagnostico."],["Farmaco topico adatto alle palpebre:",["Clobetasolo","Tacrolimus","Isotretinoina","Permetrina"],1,"Non causa atrofia."],["La DA tende a migliorare:",["In inverno","In estate","Con la lana","Con i detergenti aggressivi"],1,"Effetto del sole e dell’umidità."]],
gap:[["Il primo biologico per la DA è il ___.","dupilumab",[]],["La DA si associa ad asma e rinite nella marcia ___.","atopica",[]],["Gli inibitori della ___ topici sono adatti al volto.","calcineurina",[]]],
match:[["Filaggrina","Barriera"],["Dupilumab","IL-4Rα"],["Tacrolimus","Volto"],["Lattante","Guance"],["HSV","Eczema erpetico"]],
open:[["Descrivi la patogenesi della dermatite atopica.","Difetto genetico della barriera (filaggrina) con xerosi e perdita d’acqua, ingresso di allergeni e irritanti, risposta infiammatoria Th2 (IL-4, IL-13, IL-31) e IgE elevate, colonizzazione da S. aureus, circolo vizioso prurito-grattamento.",["filaggrina","barriera","Th2","IL-4","IgE","aureus"]],["Qual è l’approccio terapeutico a gradini?","Emollienti e cura della barriera sempre; corticosteroidi topici e inibitori della calcineurina nelle fasi acute; fototerapia; sistemici nelle forme moderate-gravi (ciclosporina, dupilumab e altri biologici, JAK inibitori); antistaminici e antibiotici se servono.",["emollient","cortico","calcineurina","fototerapia","ciclosporina","dupilumab"]]],
recap:["Cronico-recidivante, Th2 e IgE.","Filaggrina → barriera difettosa.","Lattante: guance; bambino: pieghe; adulto: volto e mani.","Diagnosi clinica con criteri maggiori/minori.","Emollienti, steroidi topici, tacrolimus, dupilumab, JAK inibitori."]});

C({id:5,t:"Dermatite seborroica e acne",sub:"Aree sebacee, comedoni, terapia",
topics:[
["Dermatite seborroica",["Dermatite delle aree sebacee: cuoio capelluto, sopracciglia, solchi naso-genieni, regione retroauricolare, presternale.","Chiazze eritematose con squame giallastre untuose; forfora come forma minima.","Ruolo di Malassezia, seborrea, stress, freddo; più frequente e grave in HIV e Parkinson.","Lattante: crosta lattea (primi mesi), si risolve spontaneamente; può ricomparire in età adulta e senile, più nei maschi.","Terapia: shampoo e creme antimicotiche (ketoconazolo, ciclopirox), cheratolitici, steroidi a bassa potenza per brevi cicli."],"Seborroica = squame GIALLE e UNTE dove c’è SEBO."],
["Acne: patogenesi",["Malattia dell’unità pilo-sebacea con 4 fattori: seborrea (androgeni), ipercheratosi follicolare (microcomedone), Cutibacterium acnes, infiammazione.","Il microcomedone è la prima lesione, non ancora visibile.","C. acnes produce lipasi e proteasi e attiva la cascata infiammatoria.","Fattori aggravanti: fumo, dieta ad alto indice glicemico e latticini (dibattuto), cosmetici comedogenici, farmaci (steroidi, litio), stress."],"I 4 fattori: SEBO, TAPPO, BATTERIO, INFIAMMAZIONE."],
["Acne: clinica e forme",["Lesioni non infiammatorie: comedoni aperti (punti neri) e chiusi (punti bianchi).","Lesioni infiammatorie: papule, pustole, noduli, cisti; esiti cicatriziali e iperpigmentazioni.","Sedi: volto, dorso, torace (aree ricche di ghiandole sebacee).","Forme: comedonica, papulo-pustolosa, nodulo-cistica, conglobata, fulminans (con sintomi sistemici), acne escoriata, da farmaci, tardiva della donna (iperandrogenismo, ovaio policistico)."],"Comedone APERTO = nero (melanina ossidata); CHIUSO = bianco."],
["Acne: terapia",["Topica: retinoidi (tretinoina, adapalene: comedolitici, anche nelle aree non ancora colpite), benzoil perossido (antibatterico, niente resistenze), acido azelaico, antibiotici topici (clindamicina) sempre in associazione.","Sistemica: tetracicline (doxiciclina, minociclina) per 3 mesi associate a topici; mai antibiotico in monoterapia.","Donna: terapia ormonale (estro-progestinici antiandrogenici, spironolattone).","Isotretinoina orale: forme nodulo-cistiche o resistenti; teratogena (contraccezione obbligatoria), secchezza mucose, aumento lipidi e transaminasi, controllo del tono dell’umore.","Mantenimento con retinoidi topici; dermocosmesi: detergenti delicati, prodotti non comedogenici, fotoprotezione (molti farmaci fotosensibilizzanti)."],"Isotretinoina = TERATOGENA: niente gravidanza, controlli ematici."]
],
fc:[["Prima lesione dell’acne?","Il microcomedone."],["Batterio coinvolto?","Cutibacterium (Propionibacterium) acnes."],["Perché associare benzoil perossido agli antibiotici?","Riduce lo sviluppo di resistenze batteriche."],["Rischio principale dell’isotretinoina?","Teratogenicità."],["Lieviti nella dermatite seborroica?","Malassezia."]],
mcq:[["Antibiotico sistemico di scelta nell’acne:",["Ciprofloxacina","Doxiciclina","Amoxicillina","Vancomicina"],1,"Tetracicline per circa 3 mesi."],["Squame giallastre untuose ai solchi naso-genieni:",["Psoriasi","Dermatite seborroica","Rosacea","Lupus"],1,"Area seborroica."],["Il retinoide topico agisce soprattutto:",["Uccidendo i batteri","Come comedolitico","Riducendo gli androgeni","Come antistaminico"],1,"Previene il microcomedone."],["L’acne fulminans si caratterizza per:",["Solo comedoni","Sintomi sistemici (febbre, artralgie)","Esordio senile","Assenza di infiammazione"],1,"Forma grave e acuta."],["Durante isotretinoina si controllano:",["Lipidi e transaminasi","Solo la glicemia","Nulla","Il PSA"],0,"Insieme alla contraccezione."]],
gap:[["I comedoni aperti sono detti punti ___.","neri",[]],["La crosta ___ è la dermatite seborroica del lattante.","lattea",[]],["L’isotretinoina è ___: richiede contraccezione.","teratogena",[]]],
match:[["Malassezia","Seborroica"],["C. acnes","Acne"],["Adapalene","Comedolitico"],["Isotretinoina","Teratogena"],["Doxiciclina","3 mesi"]],
open:[["Quali sono i fattori patogenetici dell’acne?","Seborrea sotto stimolo androgenico, ipercheratosi follicolare con formazione del microcomedone, proliferazione di Cutibacterium acnes, infiammazione; fattori aggravanti come fumo, dieta, cosmetici e farmaci.",["seborrea","androgen","ipercheratosi","comedone","acnes","infiamm"]],["Descrivi la terapia dell’acne in base alla gravità.","Lieve: retinoidi topici, benzoil perossido, acido azelaico, antibiotico topico in associazione. Moderata: aggiunta di tetracicline orali per circa 3 mesi o terapia ormonale nella donna. Grave nodulo-cistica: isotretinoina orale con contraccezione e controlli. Mantenimento con retinoidi topici.",["retinoid","benzoil","tetraciclin","ormonal","isotretinoina","mantenimento"]]],
recap:["Seborroica: squame gialle in aree sebacee, Malassezia.","Acne: sebo, tappo, C. acnes, infiammazione.","Microcomedone = prima lesione.","Topici: retinoidi + benzoil perossido; mai antibiotico da solo.","Isotretinoina nelle gravi: teratogena."]});

C({id:6,t:"Rosacea",sub:"Quattro forme, varianti, terapia",
topics:[
["Inquadramento",["Dermatosi infiammatoria cronica del volto centrale (guance, naso, fronte, mento).","Più comune nelle donne con fototipo chiaro, età adulta; forme fimatose più frequenti negli uomini.","Patogenesi: disregolazione immunitaria innata, alterazioni neurovascolari, Demodex folliculorum, UV.","Trigger: sole, calore, alcol, cibi piccanti, bevande calde, stress, sbalzi termici.","Differenza dall’acne: nella rosacea NON ci sono comedoni."],"Rosacea = acne SENZA comedoni + rossore centrale."],
["Le quattro forme",["1) Eritemato-teleangectasica: flushing (vampate di circa 10 minuti), eritema persistente (couperose), teleangectasie.","2) Papulo-pustolosa: papule e pustole sull’eritema, possibile edema.","3) Fimatosa: ispessimento e nodularità del tessuto, soprattutto rinofima (naso), poi gnatofima, metofima, otofima, blefarofima.","4) Oculare: blefarite, congiuntivite, sensazione di corpo estraneo, cheratite."],"Le 4 forme in ordine: ROSSO → BRUFOLI → BOZZE (fima) → OCCHIO."],
["Varianti",["Rosacea ghiandolare: cute spessa e seborroica, papule e noduli, prevalentemente uomini.","Rosacea granulomatosa: papule e noduli giallo-bruni, anche periorali e perioculari, aspetto granulomatoso all’istologia.","Esistono forme familiari."],"Granulomatosa = papule GIALLO-BRUNE anche intorno agli occhi."],
["Terapia",["Fotoprotezione, evitare i trigger, detersione delicata.","Topici: metronidazolo, acido azelaico, ivermectina (contro Demodex), brimonidina e oximetazolina (eritema).","Sistemici: doxiciclina a basso dosaggio (antinfiammatoria), isotretinoina a basse dosi nelle forme resistenti.","Laser e luce pulsata per teleangectasie; chirurgia o laser per il fima (terapia demolitiva-ricostruttiva)."],"Rosso → brimonidina/laser; brufoli → ivermectina, metronidazolo, doxiciclina; fima → chirurgia."]
],
fc:[["Cosa manca nella rosacea rispetto all’acne?","I comedoni."],["Cos’è il rinofima?","Ispessimento nodulare del naso nella rosacea fimatosa."],["Acaro coinvolto?","Demodex folliculorum."],["Terapia topica antiparassitaria?","Ivermectina."],["Durata tipica di un flushing?","Circa 10 minuti."]],
mcq:[["Uomo di 60 anni con naso bulboso e ispessito:",["Rosacea fimatosa","Acne conglobata","Lupus","Psoriasi"],0,"Rinofima."],["Rossore centrofacciale con pustole e nessun comedone:",["Acne vulgaris","Rosacea papulo-pustolosa","Dermatite seborroica","Tinea faciei"],1,"Assenza di comedoni."],["Trattamento del fima conclamato:",["Solo topici","Chirurgia o laser","Antistaminici","Nessuno"],1,"Terapia demolitiva-ricostruttiva."],["Quale non è un trigger tipico?",["Alcol","Calore","Cibi piccanti","Freddo secco come unica causa di comedoni"],3,"I comedoni non fanno parte della rosacea."],["La doxiciclina nella rosacea si usa a dosaggio:",["Basso, antinfiammatorio","Altissimo","Endovena","Unico"],0,"Effetto non antibiotico."]],
gap:[["La rosacea colpisce più spesso le donne con fototipo ___.","chiaro",["chiari"]],["L’eritema persistente della rosacea è detto ___.","couperose",[]],["La forma che coinvolge palpebre e congiuntive è la rosacea ___.","oculare",[]]],
match:[["Flushing","Eritemato-teleangectasica"],["Rinofima","Fimatosa"],["Blefarite","Oculare"],["Demodex","Ivermectina"],["Teleangectasie","Laser"]],
open:[["Descrivi le quattro forme cliniche di rosacea.","Eritemato-teleangectasica con flushing, eritema persistente e teleangectasie; papulo-pustolosa con papule e pustole senza comedoni; fimatosa con ispessimento nodulare (rinofima, gnatofima, metofima, otofima, blefarofima); oculare con blefarite, congiuntivite e cheratite.",["eritemato","flushing","papulo","fimatosa","rinofima","oculare"]],["Quali sono le opzioni terapeutiche della rosacea?","Fotoprotezione ed evitamento dei trigger; topici come metronidazolo, acido azelaico, ivermectina e brimonidina; doxiciclina a basso dosaggio o isotretinoina a basse dosi; laser e luce pulsata; chirurgia per il fima.",["fotoprotez","metronidazolo","ivermectina","brimonidina","doxiciclina","laser"]]],
recap:["Volto centrale, donne di fototipo chiaro.","Nessun comedone.","4 forme: eritemato-teleangectasica, papulo-pustolosa, fimatosa, oculare.","Trigger: sole, calore, alcol, piccante.","Ivermectina, metronidazolo, doxiciclina, laser, chirurgia del fima."]});

C({id:7,t:"Psoriasi",sub:"Forme, comorbidità, terapia",
topics:[
["Patogenesi",["Malattia infiammatoria cronica immunomediata con predisposizione genetica (HLA-Cw6).","Asse IL-23/Th17 (IL-17) e TNF-α: iperproliferazione dei cheratinociti.","Turnover accelerato: 3-4 giorni invece di 28-30.","Istologia: paracheratosi con neutrofili (microascessi di Munro), acantosi, papille allungate con capillari dilatati, assenza dello strato granuloso.","Fattori scatenanti: traumi (Koebner), infezioni streptococciche (forma guttata), stress, farmaci (litio, β-bloccanti, antimalarici), sospensione brusca di steroidi sistemici, alcol, fumo."],"Psoriasi = IL-23/IL-17: i bersagli dei farmaci biologici."],
["Forme cliniche",["A placche (volgare): la più comune; placche eritematose ben delimitate con squame argentee su gomiti, ginocchia, regione sacrale, cuoio capelluto.","Guttata: piccole papule a goccia nei giovani dopo faringite streptococcica.","Inversa: pieghe, senza squame.","Palmo-plantare: limitata ma invalidante, fissurazioni, spesso resistente.","Ungueale: pitting (a ditale da cucito), macchie a olio, onicolisi; molto frequente in chi ha artrite psoriasica (≈70%).","Pustolosa (generalizzata di von Zumbusch o localizzata palmo-plantare) ed eritrodermica (>90% della superficie, emergenza)."],"Unghie colpite? Cerca l’ARTRITE psoriasica."],
["Artrite e comorbidità",["Artrite psoriasica: oligoartrite, interfalangee distali, dattilite (dito a salsicciotto), entesite, spondilite; FR negativo.","Psoriasi come malattia sistemica: sindrome metabolica, obesità, diabete, dislipidemia, ipertensione, rischio cardiovascolare aumentato.","Altre: uveite, malattie infiammatorie intestinali (Crohn), steatosi epatica, depressione e impatto psicosociale."],"Psoriasi = malattia della pelle CON un cuore e un metabolismo a rischio."],
["Diagnosi e indici di gravità",["Diagnosi clinica; segni della candela, membrana di Duncan-Buckley, Auspitz, Koebner.","Istologia nelle forme atipiche, resistenti, palmo-plantari, genitali o lesioni singole.","Indici: PASI (estensione e gravità), BSA (superficie), NAPSI (unghie), DLQI (qualità di vita).","Forma moderata-grave (es. PASI o BSA >10) o sedi sensibili (volto, genitali, mani, unghie) → terapia sistemica."],"Regola del 10: PASI, BSA o DLQI >10 → terapia sistemica."],
["Terapia",["Topica: corticosteroidi, analoghi della vitamina D (calcipotriolo), spesso in associazione; cheratolitici (acido salicilico).","Fototerapia: UVB a banda stretta, PUVA.","Sistemica tradizionale: metotrexato (epatotossico, iperomocisteinemia, teratogeno), ciclosporina (nefrotossica, ipertensione), acitretina (teratogena), apremilast (inibitore PDE4).","Biologici: anti-TNF (adalimumab, etanercept, infliximab), anti-IL-12/23 (ustekinumab), anti-IL-17 (secukinumab, ixekizumab, bimekizumab), anti-IL-23 (guselkumab, risankizumab, tildrakizumab).","Prima dei biologici: screening per TB latente (Quantiferon), HBV, HCV, HIV."],"Biologici: TNF, 12/23, 17, 23. E prima sempre il QUANTIFERON."]
],
fc:[["Turnover epidermico nella psoriasi?","3-4 giorni."],["Forma più comune?","Psoriasi a placche (volgare)."],["Infezione che scatena la forma guttata?","Faringite streptococcica."],["Segno ungueale tipico?","Pitting (unghia a ditale da cucito)."],["Cosa fare prima di un biologico?","Screening per TB latente, epatiti e HIV."],["Cos’è il PASI?","Indice di estensione e gravità della psoriasi."]],
mcq:[["Giovane con papule a goccia dopo mal di gola:",["Pitiriasi rosea","Psoriasi guttata","Varicella","Lichen planus"],1,"Dopo faringite streptococcica."],["Interessamento delle interfalangee distali e dito a salsicciotto:",["Artrite reumatoide","Artrite psoriasica","Gotta","Artrosi"],1,"Dattilite."],["Farmaco che può peggiorare la psoriasi:",["Litio","Paracetamolo","Amoxicillina","Ferro"],0,"Anche β-bloccanti e antimalarici."],["Ustekinumab blocca:",["TNF-α","IL-12/23","IL-17","IL-4"],1,"Subunità p40."],["Microascessi di Munro sono raccolte di:",["Eosinofili","Neutrofili","Linfociti B","Mastociti"],1,"Nello strato corneo paracheratosico."],["Emergenza dermatologica tra le forme di psoriasi:",["Guttata","Eritrodermica","A placche limitata","Ungueale"],1,"Coinvolge quasi tutta la cute."]],
gap:[["La psoriasi eritrodermica coinvolge oltre il ___% della superficie corporea.","90",[]],["L’analogo topico della vitamina D è il ___.","calcipotriolo",[]],["L’asse patogenetico principale è IL-23/___.","Th17",["IL-17","il17"]]],
match:[["Guttata","Streptococco"],["Unghie","Pitting"],["Metotrexato","Epatotossico"],["Ciclosporina","Nefrotossica"],["Secukinumab","Anti-IL-17"]],
open:[["Descrivi la patogenesi e l’istologia della psoriasi.","Malattia immunomediata con predisposizione genetica, asse IL-23/Th17 e TNF-α che induce iperproliferazione dei cheratinociti (turnover 3-4 giorni). Istologia: paracheratosi con microascessi di Munro, acantosi, assenza dello strato granuloso, papille allungate con capillari dilatati.",["IL-23","IL-17","TNF","3-4","paracheratosi","Munro"]],["Perché la psoriasi è considerata una malattia sistemica?","Si associa ad artrite psoriasica, sindrome metabolica, obesità, diabete, dislipidemia, ipertensione e aumento del rischio cardiovascolare, malattie infiammatorie intestinali, uveite, steatosi epatica e depressione.",["artrite","metabolic","obesità","cardiovascolar","Crohn","depression"]],["Riassumi le opzioni terapeutiche della psoriasi.","Topici (steroidi, calcipotriolo, cheratolitici), fototerapia (UVB, PUVA), sistemici tradizionali (metotrexato, ciclosporina, acitretina, apremilast), biologici anti-TNF, anti-IL-12/23, anti-IL-17, anti-IL-23, previo screening per TB, epatiti e HIV.",["topic","fototerapia","metotrexato","ciclosporina","biologic","TB"]]],
recap:["IL-23/IL-17 e TNF; turnover 3-4 giorni.","Placche argentee su gomiti, ginocchia, sacro, cuoio capelluto.","Guttata dopo streptococco; unghie → artrite.","Comorbidità metaboliche e cardiovascolari.","Topici → fototerapia → sistemici → biologici (screening TB)."]});
C({id:8,t:"Dermatosi bollose autoimmuni",sub:"Pemfigo, pemfigoide, Dühring",
topics:[
["Pemfigo: patogenesi",["Bolle intraepidermiche da autoanticorpi IgG contro le desmogleine (caderine dei desmosomi).","DSG3 (130 kDa) negli strati profondi; DSG1 (160 kDa) superficiale, prevalente nelle aree seborroiche.","Il legame delle IgG causa ACANTOLISI: perdita di coesione tra cheratinociti.","Più frequente nelle popolazioni ebrea e mediterranea, adulti di mezza età."],"PEMFIGO = PIÙ in alto (dentro l’epidermide), acantolisi."],
["Forme di pemfigo",["Volgare: anti-DSG3 (mucoso) o DSG3+DSG1 (muco-cutaneo); esordio frequente con erosioni orali dolorose; bolle flaccide, fragili, senza alone eritematoso, che lasciano erosioni.","Foliaceo e seborroico (eritematoso): anti-DSG1, clivaggio superficiale subcorneo, squame-croste su aree seborroiche, mucose risparmiate (aspetto a pasta sfoglia).","Vegetante: variante del volgare con lesioni vegetanti nelle pieghe.","Paraneoplastico: associato a linfomi e neoplasie, grave mucosite.","Segno di Nikolsky positivo; un tempo letale, oggi controllato dalla terapia."],"Bocca prima della pelle → pemfigo VOLGARE (DSG3)."],
["Pemfigoide e altre subepidermiche",["Pemfigoide bolloso: anziani; autoanticorpi contro BP180 e BP230 della GDE; bolle tese, robuste, su base eritematosa, prurito intenso; mucose raramente coinvolte; Nikolsky negativo.","Pemfigoide gravidico (herpes gestationis): in gravidanza, periombelicale.","Pemfigoide cicatriziale (delle mucose): mucose orali e oculari con esiti cicatriziali.","Dermatite erpetiforme di Dühring: associata a celiachia; vescicole raggruppate pruriginosissime su superfici estensorie e glutei; IgA granulari nelle papille dermiche; dieta senza glutine e dapsone.","Dermatosi a IgA lineari; epidermolisi bollosa acquisita (anti-collagene VII)."],"Pemfigoide = anziano, bolle TESE, prurito, prognosi migliore."],
["Diagnosi e terapia",["Biopsia per istologia (sede del clivaggio) + immunofluorescenza diretta su cute perilesionale.","IFD pemfigo: IgG e C3 intercellulari a rete (aspetto a rete di pesca); pemfigoide: deposito lineare lungo la GDE.","IFI su siero e ELISA per anti-DSG1/DSG3 e anti-BP180/BP230 (monitoraggio di attività).","Citodiagnosi di Tzanck: cellule acantolitiche nel pemfigo.","Terapia: corticosteroidi sistemici, immunosoppressori (azatioprina, micofenolato), rituximab (anti-CD20) nel pemfigo; steroidi topici potenti (clobetasolo) e doxiciclina nel pemfigoide."],"IFD: pemfigo a RETE, pemfigoide LINEARE."]
],
fc:[["Bersaglio del pemfigo volgare?","Desmogleina 3 (± desmogleina 1)."],["Bersagli del pemfigoide bolloso?","BP180 e BP230."],["Aspetto all’IFD nel pemfigo?","Depositi intercellulari a rete."],["Dermatite di Dühring si associa a?","Celiachia."],["Farmaco biologico nel pemfigo?","Rituximab (anti-CD20)."]],
mcq:[["Anziano con bolle tese e prurito, mucose integre:",["Pemfigo volgare","Pemfigoide bolloso","Dühring","Pemfigo foliaceo"],1,"Bolla subepidermica."],["Il segno di Nikolsky è positivo in:",["Pemfigoide","Pemfigo","Dühring","Orticaria"],1,"Acantolisi."],["Il pemfigo foliaceo colpisce:",["DSG3, mucose","DSG1, clivaggio superficiale","BP180","Collagene VII"],1,"Risparmia le mucose."],["Vescicole raggruppate pruriginose ai gomiti in un celiaco:",["Pemfigoide","Dühring","Herpes zoster","Scabbia"],1,"IgA nelle papille."],["Esame chiave per la diagnosi di malattia bollosa:",["Patch test","Immunofluorescenza diretta","Prick test","Lampada di Wood"],1,"Su cute perilesionale."]],
gap:[["La perdita di coesione tra cheratinociti si chiama ___.","acantolisi",[]],["Nel pemfigoide il deposito all’IFD è ___.","lineare",[]],["La terapia della Dühring prevede dieta senza glutine e ___.","dapsone",[]]],
match:[["Pemfigo volgare","DSG3"],["Pemfigo foliaceo","DSG1"],["Pemfigoide","BP180"],["Dühring","IgA"],["EBA","Collagene VII"]],
open:[["Fai la diagnosi differenziale tra pemfigo e pemfigoide.","Pemfigo: adulti, IgG anti-desmogleine, bolla intraepidermica acantolitica, bolle flaccide fragili, mucose spesso coinvolte, Nikolsky positivo, IFD intercellulare a rete. Pemfigoide: anziani, anti-BP180/BP230, bolla subepidermica, bolle tese su base eritematosa con prurito, mucose raramente, Nikolsky negativo, IFD lineare alla GDE.",["desmogleina","intraepidermic","flaccid","Nikolsky","BP180","subepidermic","tese","lineare"]],["Come si diagnostica una dermatosi bollosa autoimmune?","Biopsia di una bolla recente per l’istologia (livello del clivaggio) e biopsia perilesionale per l’immunofluorescenza diretta; immunofluorescenza indiretta e ELISA sul siero per gli autoanticorpi specifici; citodiagnosi di Tzanck nel pemfigo.",["biopsia","istolog","immunofluorescenza","ELISA","Tzanck"]]],
recap:["Pemfigo: IgG anti-DSG, intraepidermico, acantolisi, Nikolsky+.","Volgare DSG3 (bocca), foliaceo DSG1 (superficiale).","Pemfigoide: anziani, BP180/230, bolle tese, prurito.","IFD: rete vs lineare.","Dühring: celiachia, IgA, dapsone e niente glutine."]});

C({id:9,t:"Micosi cutanee",sub:"Dermatofiti, Candida, terapia",
topics:[
["Dermatofiti",["Funghi cheratinofili: Trichophyton, Microsporum, Epidermophyton.","Antropofili (uomo), zoofili (animali: M. canis da cani e gatti, T. mentagrophytes), geofili (terreno).","Le forme zoofile danno quadri più infiammatori.","Diagnosi: esame microscopico diretto con KOH, esame colturale (Sabouraud), lampada di Wood (fluorescenza verde in alcune tinee microsporiche)."],"Zoofilo = più infiammato: il fungo ‘non è abituato’ all’uomo."],
["Le tinee",["Corporis: chiazze anulari con bordo periferico eritemato-desquamativo attivo e centro più chiaro, talvolta anelli concentrici.","Faciei (bambini), cruris (inguine, maschi, risparmia lo scroto), pedis (interdigitale, ‘piede d’atleta’), manuum (spesso una sola mano: ‘due piedi e una mano’).","Capitis: bambini; microsporica (chiazze grandi, peli spezzati alla stessa altezza) e tricofitica (piccole chiazze, peli spezzati a punti neri); kerion (forma infiammatoria suppurativa).","Barbae e unguium (onicomicosi).","Tinea incognita: tinea modificata dall’uso improprio di steroidi topici."],"Tinea = cerchio che si ALLARGA con bordo attivo e centro che guarisce."],
["Candida e lieviti",["Candida albicans: commensale opportunista; favorita da umidità, diabete, obesità, antibiotici, immunodepressione.","Intertrigine: pieghe eritematose, umide, con lesioni satellite periferiche (pustoline).","Perlèche (cheilite angolare), mughetto orale, balanopostite, vulvovaginite.","Onicomicosi e perionissi da Candida (paronichia con unghie dolenti).","Pityriasis versicolor (Malassezia): macchie ipo- o ipercromiche con fine desquamazione (segno del colpo d’unghia)."],"Candida = lesioni SATELLITI fuori dalla chiazza principale."],
["Terapia",["Topica (forme localizzate): azoli (clotrimazolo, ketoconazolo), allilamine (terbinafina), ciclopiroxolamina, amorolfina (smalto per onicomicosi).","Sistemica (tinea capitis, onicomicosi estese, forme diffuse): terbinafina (dermatofiti), itraconazolo, fluconazolo (Candida), griseofulvina (tinea capitis nel bambino).","Gli azoli inibiscono la sintesi dell’ergosterolo (lanosterolo demetilasi); la terbinafina blocca la squalene epossidasi.","Fallimenti: terapie incongrue (steroidi → tinea incognita), durata insufficiente, scarsa aderenza, reinfezione.","Prevenzione: asciugare le pieghe, calzature traspiranti, trattare gli animali."],"Terbinafina = dermatofiti; fluconazolo = Candida."]
],
fc:[["Generi dei dermatofiti?","Trichophyton, Microsporum, Epidermophyton."],["Esame microscopico rapido delle squame?","Preparato con KOH."],["Cos’è la tinea incognita?","Tinea alterata dall’applicazione di steroidi topici."],["Lesioni satellite tipiche di?","Candidosi delle pieghe."],["Meccanismo della terbinafina?","Inibizione della squalene epossidasi."]],
mcq:[["Chiazza anulare con bordo attivo desquamante e centro chiaro:",["Psoriasi","Tinea corporis","Eczema nummulare sempre","Vitiligine"],1,"Aspetto tipico."],["Bambino con chiazze alopeciche, peli spezzati, gatto in casa:",["Alopecia areata","Tinea capitis microsporica","Psoriasi","Lichen"],1,"M. canis."],["Terapia sistemica della tinea capitis:",["Solo topici","Terbinafina o griseofulvina orale","Antibiotici","Corticosteroidi"],1,"I topici non raggiungono il follicolo."],["Intertrigine sottomammaria con pustoline satelliti:",["Dermatofita","Candida","Psoriasi inversa","Eritrasma"],1,"Lesioni satellite."],["Smalto antimicotico per onicomicosi:",["Amorolfina","Permetrina","Tacrolimus","Benzoil perossido"],0,"Anche ciclopirox."]],
gap:[["Il terreno di coltura per i miceti è quello di ___.","Sabouraud",[]],["La tinea pedis interdigitale è detta ‘piede d’___’.","atleta",[]],["Gli azoli inibiscono la sintesi dell’___.","ergosterolo",[]]],
match:[["M. canis","Gatto"],["Tinea cruris","Inguine"],["Candida","Satelliti"],["Malassezia","Pityriasis versicolor"],["Terbinafina","Squalene epossidasi"]],
open:[["Come si diagnostica una micosi cutanea?","Clinica, esame microscopico diretto delle squame con KOH, esame colturale su terreno di Sabouraud per identificare la specie, lampada di Wood per alcune forme.",["KOH","colturale","Sabouraud","Wood"]],["Quando serve una terapia sistemica nelle dermatofitosi?","Tinea capitis, onicomicosi estese o con interessamento della matrice, forme diffuse o resistenti ai topici, immunodepressi; si usano terbinafina, itraconazolo o griseofulvina.",["capitis","onicomicos","estese","terbinafina","itraconazolo"]]],
recap:["Dermatofiti: Trichophyton, Microsporum, Epidermophyton.","Tinea: anello con bordo attivo.","Capitis nel bambino: terapia orale.","Candida: pieghe, lesioni satelliti.","Azoli → ergosterolo; terbinafina → squalene epossidasi.","Steroidi su una tinea = tinea incognita."]});

C({id:10,t:"Infezioni virali cutanee",sub:"HSV, VZV, HPV ed esantemi",
topics:[
["Herpes simplex",["HSV-1 (distretto cefalico) e HSV-2 (genitale), ma entrambi possibili in entrambe le sedi.","Siero-prevalenza alta: oltre il 90% degli adulti ha anticorpi anti-HSV-1, oltre il 30% anti-HSV-2.","Primoinfezione spesso inapparente o gengivostomatite; latenza nei gangli; recidive scatenate da febbre, sole, stress, ciclo mestruale.","Clinica: prodromi (bruciore), vescicole raggruppate a grappolo su base eritematosa, erosioni, croste.","Diagnosi: clinica, Tzanck (cellule giganti multinucleate), PCR.","Terapia: aciclovir, valaciclovir, famciclovir; soppressiva se recidive frequenti."],"Herpes = vescicole a GRAPPOLO che tornano sempre nello stesso posto."],
["Varicella e zoster",["Varicella: esantema vescicoloso pruriginoso a cielo stellato (lesioni in stadi diversi), anche sul cuoio capelluto e mucose.","Zoster: riattivazione del VZV dal ganglio sensitivo, più frequente sopra i 50 anni e negli immunodepressi.","Dolore prodromico, poi vescicole a grappolo unilaterali lungo un dermatomero, senza superare la linea mediana.","Complicanze: nevralgia post-erpetica, zoster oftalmico, sindrome di Ramsay Hunt (paralisi facciale, vescicole auricolari), zoster disseminato.","Terapia: antivirali entro 72 ore (valaciclovir, famciclovir, aciclovir), analgesici; vaccino ricombinante dopo i 50 anni."],"Zoster: DOLORE prima, vescicole dopo, una SOLA metà del corpo."],
["HPV: verruche e condilomi",["HPV infetta i cheratinociti e accelera le mitosi → iperplasia.","Si parla di genotipi (non sierotipi): HPV 1, 2, 27, 57 verruche cutanee; 6 e 11 condilomi (basso rischio); 16, 18, 31 alto rischio oncogeno (cervice, pene).","Verruche volgari: papule cheratosiche rugose (dorso mani, dita, periungueali); plantari endofitiche e dolorose con punti neri (capillari trombizzati); a mosaico; piane; filiformi.","Trasmissione per contatto diretto o indiretto (ciabatte), autoinoculazione; picco 12-16 anni.","Condilomi acuminati: genitali e perianali, trasmissione sessuale.","Terapia: crioterapia, cheratolitici, laser, imiquimod; vaccino (bivalente 16/18, tetravalente 6/11/16/18, nonavalente)."],"6 e 11 = verruche genitali benigne; 16 e 18 = cancro."],
["Altri esantemi virali",["Malattia mani-piedi-bocca (Coxsackie): febbre, vescicole orali e palmo-plantari incassate e dolorose; terapia di supporto.","Pitiriasi rosea di Gibert: chiazza madre seguita da chiazze ovalari lungo le linee di clivaggio ‘ad albero di Natale’; autolimitante in 6-8 settimane.","Mollusco contagioso (poxvirus): papule ombelicate perlacee, bambini e immunodepressi.","DD di esantema palmo-plantare: sifilide secondaria, rickettsiosi, mani-piedi-bocca."],"Pitiriasi rosea: prima la MADRE, poi l’ALBERO DI NATALE."]
],
fc:[["Cosa mostra il test di Tzanck nell’herpes?","Cellule giganti multinucleate."],["Entro quando trattare lo zoster?","Entro 72 ore dall’esordio delle vescicole."],["Genotipi HPV dei condilomi?","6 e 11."],["Genotipi HPV ad alto rischio?","16 e 18 (anche 31)."],["Chiazza madre?","Prima lesione della pitiriasi rosea di Gibert."]],
mcq:[["Verruca plantare con punti neri:",["Capillari trombizzati","Melanina","Spore fungine","Sangue secco superficiale e basta"],0,"Superficializzazione dei capillari dermici."],["Vescicole auricolari e paralisi facciale:",["Bell","Ramsay Hunt","Herpes labiale","Lyme sempre"],1,"Zoster del ganglio genicolato."],["Lesioni ovalari sul tronco ad albero di Natale dopo una chiazza grande:",["Psoriasi guttata","Pitiriasi rosea","Tinea corporis","Sifilide"],1,"Autolimitante."],["Il vaccino tetravalente copre:",["16, 18","6, 11, 16, 18","1, 2, 27","31, 33"],1,"Gardasil."],["Mollusco contagioso: lesione tipica",["Papula ombelicata perlacea","Pomfo","Bolla tesa","Placca argentea"],0,"Da poxvirus."]],
gap:[["Lo zoster non supera la linea ___.","mediana",[]],["Le verruche plantari crescono in senso ___ per la pressione.","endofitico",["endofitica","verso l'interno"]],["La malattia mani-piedi-bocca è causata da ___virus.","Coxsackie",["Coxsackie virus","enterovirus"]]],
match:[["HSV","Grappolo"],["VZV","Dermatomero"],["HPV 6-11","Condilomi"],["Coxsackie","Mani-piedi-bocca"],["Poxvirus","Mollusco"]],
open:[["Descrivi clinica, complicanze e terapia dell’herpes zoster.","Riattivazione del VZV latente nel ganglio sensitivo, soprattutto anziani e immunodepressi; dolore prodromico seguito da vescicole a grappolo unilaterali lungo un dermatomero; complicanze: nevralgia post-erpetica, zoster oftalmico, Ramsay Hunt, forme disseminate; antivirali entro 72 ore e analgesici; vaccinazione.",["riattivaz","ganglio","dermatom","nevralgia","72","vaccin"]],["Classifica le manifestazioni da HPV e i genotipi coinvolti.","Verruche volgari, plantari, piane e filiformi (HPV 1, 2, 27, 57); condilomi acuminati genitali (HPV 6 e 11); lesioni displastiche e carcinomi di cervice e pene (HPV 16, 18, 31); epidermodisplasia verruciforme. Prevenzione con vaccini.",["verruch","plantari","condilom","6","16","vaccin"]]],
recap:["HSV: vescicole a grappolo, Tzanck, aciclovir.","Zoster: dermatomero, antivirale entro 72 ore.","HPV: 1/2 verruche, 6/11 condilomi, 16/18 cancro.","Verruche plantari endofitiche con punti neri.","Pitiriasi rosea: chiazza madre + albero di Natale."]});

C({id:11,t:"Ectoparassitosi",sub:"Scabbia e pediculosi",
topics:[
["Scabbia: agente e trasmissione",["Sarcoptes scabiei var. hominis, acaro di 0,4 mm, non visibile a occhio nudo; cheratinofilo obbligato.","La femmina scava un cunicolo nello strato corneo e depone circa 3 uova al giorno; muore dopo circa 10 giorni senza tornare indietro.","Prurito da sensibilizzazione allergica all’acaro, uova e feci (non dallo scavo).","Incubazione: 2-4 settimane al primo contagio, 1-3 giorni nella reinfestazione.","Contagio diretto cute-cute prolungato (anche sessuale) e indiretto (lenzuola, asciugamani); sopravvivenza fuori dall’ospite limitata.","Malattia soggetta a notifica."],"Scabbia: prurito NOTTURNO che colpisce TUTTA la famiglia."],
["Scabbia: clinica",["Prurito intenso, notturno, ‘biopsiante’ con lesioni da grattamento.","Lesione patognomonica: cunicolo serpiginoso di 5-10 mm con eminenza acarica a un’estremità.","Altre primitive: papule, vescicole, raramente pustole; noduli scabbiosi (genitali, ascelle).","Sedi: spazi interdigitali, polsi, gomiti, ascelle, areole, ombelico, genitali (asta del pene), glutei; risparmio del volto nell’adulto.","Secondarie: escoriazioni lineari, croste, impetiginizzazione.","Scabbia crostosa (norvegese): immunodepressi, ipercheratosi con milioni di acari, altamente contagiosa."],"Prima di tutto guarda POLSI e MANI (spazi interdigitali)."],
["Scabbia: diagnosi e terapia",["Diagnosi clinica + dermatoscopia (segno del ‘deltaplano’ o triangolo all’estremità del cunicolo), raschiato con microscopio.","Permetrina 5% crema: la più usata; applicare su tutto il corpo dal collo in giù, lasciare in sede e ripetere dopo 7 giorni.","Alternative: benzoato di benzile, ivermectina orale (forme crostose, comunità).","Trattare contemporaneamente tutti i conviventi e i contatti stretti.","Lavare a 60°C biancheria e indumenti o chiuderli in un sacco per alcuni giorni.","Il prurito può persistere per settimane dopo la guarigione (non è fallimento)."],"Scabbia: tratta TUTTI insieme e lava a 60 gradi."],
["Pediculosi del capo",["Pediculus humanus var. capitis: 2-3 mm, visibile a occhio nudo, ematofago; non trasmette malattie infettive.","Più frequente nei bambini in età scolare e nelle aree urbane sovraffollate.","Lendini: uova bianche ovali adese al fusto del capello, da non confondere con la forfora (non si staccano facilmente).","Prurito retroauricolare e occipitale, escoriazioni, impetiginizzazione, linfoadenopatia.","Diagnosi: pettine a denti stretti (<0,3 mm) e lente o dermatoscopio.","Terapia: piretrine/piretroidi, malathion, dimeticone; ripetere dopo 7-10 giorni; rimozione meccanica con wet combing associata. Pthirus pubis: pediculosi del pube."],"Lendini = attaccate al capello; forfora = vola via."]
],
fc:[["Agente della scabbia?","Sarcoptes scabiei var. hominis."],["Lesione patognomonica?","Cunicolo con eminenza acarica."],["Terapia più usata?","Permetrina 5% crema, da ripetere dopo 7 giorni."],["Forma molto contagiosa negli immunodepressi?","Scabbia crostosa (norvegese)."],["Cosa sono le lendini?","Uova del pidocchio adese al fusto del capello."]],
mcq:[["Prurito notturno in tutta la famiglia, papule interdigitali:",["Dermatite atopica","Scabbia","Orticaria","Psoriasi"],1,"Contagio familiare."],["Perché la scabbia dà prurito?",["Lo scavo stimola i nervi","Reazione allergica all’acaro e ai suoi prodotti","Tossina batterica","Disidratazione"],1,"Nell’epidermide alta non ci sono terminazioni nervose."],["Dopo una terapia corretta il prurito:",["Scompare subito","Può persistere settimane","Indica sempre fallimento","Richiede antibiotico"],1,"Reazione residua."],["Il pidocchio del capo:",["Trasmette il tifo","Non trasmette malattie infettive","È invisibile","Vive mesi fuori dall’ospite"],1,"Secondo le dispense."],["Nella scabbia vanno trattati:",["Solo il paziente","Paziente e tutti i contatti stretti","Solo i bambini","Solo chi ha prurito"],1,"Contemporaneamente."]],
gap:[["L’acaro della scabbia misura circa ___ mm.","0,4",["0.4"]],["La permetrina si usa alla concentrazione del ___%.","5",["cinque"]],["L’incubazione al primo contagio è di ___-4 settimane.","2",["due"]]],
match:[["Sarcoptes","Cunicolo"],["Pediculus","Lendini"],["Permetrina","Scabbia"],["Ivermectina","Forma crostosa"],["Pthirus","Pube"]],
open:[["Descrivi la clinica e le sedi tipiche della scabbia.","Prurito intenso soprattutto notturno, spesso familiare; cunicolo serpiginoso con eminenza acarica, papule, vescicole, noduli; lesioni secondarie da grattamento, croste, impetiginizzazione; sedi: spazi interdigitali, polsi, gomiti, ascelle, areole, ombelico, genitali, glutei, con risparmio del volto nell’adulto.",["notturno","cunicolo","eminenza","interdigital","polsi","genital"]],["Qual è la gestione terapeutica della scabbia?","Permetrina 5% su tutto il corpo dal collo in giù, ripetuta dopo una settimana; ivermectina orale nelle forme crostose o epidemiche; trattamento simultaneo di tutti i contatti; lavaggio a 60°C della biancheria; antistaminici per il prurito che può persistere.",["permetrina","7","ivermectina","contatti","60"]]],
recap:["Sarcoptes 0,4 mm; prurito da ipersensibilità.","Cunicolo + eminenza acarica = diagnosi.","Polsi, mani, ombelico, genitali.","Permetrina 5% ×2, tutti i contatti, lavaggio 60°C.","Pidocchi: lendini adese, pettine fitto, piretrine."]});

C({id:12,t:"Nevi e melanoma",sub:"ABCDE, Breslow, prevenzione",
topics:[
["Nevi melanocitici",["Proliferazioni benigne di melanociti: giunzionali, composti, dermici.","Nevo di Spitz: papula rosata a rapida crescita nei bambini.","Nevo di Reed: pigmentato scuro, giovani donne, arti.","Nevo di Sutton: nevo circondato da un alone acromico.","Nevo spilus: chiazza caffellatte con punti più scuri.","Nevi displastici: atipici, grandi, irregolari; sindrome del nevo displastico → follow-up stretto e possibile asportazione preventiva."],"Spitz = bambino rosa; Reed = ragazza nera; Sutton = alone bianco."],
["Melanoma: epidemiologia e rischio",["Tumore maligno dei melanociti; picco a 40-50 anni, più nelle donne di pelle chiara.","Origina da un nevo preesistente solo in circa il 30% dei casi: più spesso da cute sana.","Fattori di rischio: fototipo chiaro, ustioni solari soprattutto in età infantile, esposizione intermittente intensa, lampade abbronzanti, numerosi nevi (>50) o nevi displastici, familiarità, immunodepressione, xeroderma pigmentoso.","Fotocarcinogenesi: danno diretto al DNA da UV e immunosoppressione cutanea."],"Ustioni da BAMBINO = rischio da ADULTO."],
["Forme cliniche",["Ad accrescimento superficiale: il più frequente, crescita orizzontale prima di quella verticale (tronco negli uomini, gambe nelle donne).","Nodulare: crescita verticale da subito, prognosi peggiore; spesso non rispetta l’ABCDE (regola EFG: elevato, fermo, crescente); può essere amelanotico.","Lentigo maligna melanoma: da lentigo maligna (in situ), volto di anziani con cute fotodanneggiata.","Acrale lentigginoso: palmo, pianta, letto ungueale; più frequente nei fototipi scuri; segno di Hutchinson (pigmento sulla plica ungueale)."],"Nodulare = scatta in VERTICALE: la forma più cattiva."],
["Diagnosi, stadiazione, terapia",["Regola ABCDE (per educare il paziente): Asimmetria, Bordi irregolari, Colore disomogeneo, Diametro >6 mm, Evoluzione.","Segno del brutto anatroccolo: il nevo diverso da tutti gli altri.","Dermatoscopia e videodermatoscopia, microscopia confocale: metodiche non invasive.","Biopsia escissionale con margini stretti (1-3 mm) per non alterare il drenaggio linfatico.","Spessore di Breslow (mm, dallo strato granuloso al punto più profondo) = principale fattore prognostico; livello di Clark (strati coinvolti); ulcerazione; indice mitotico.","Allargamento dei margini in base al Breslow, biopsia del linfonodo sentinella.","Metastatico: immunoterapia (anti-PD-1 come nivolumab e pembrolizumab, anti-CTLA-4 ipilimumab), terapia a bersaglio per BRAF mutato (BRAF + MEK inibitori)."],"ABCDE: Asimmetria, Bordi, Colore, Diametro, Evoluzione."],
["Prevenzione",["Primaria: fotoprotezione (evitare le ore centrali, indumenti, creme ad alto SPF), niente lampade abbronzanti, protezione dei bambini.","Secondaria: autoesame della cute periodico, controlli dermatologici regolari per i soggetti ad alto rischio, metodiche diagnostiche non invasive con mappatura dei nevi."],"Autoesame + controllo + fotoprotezione."]
],
fc:[["Principale fattore prognostico del melanoma primitivo?","Spessore di Breslow."],["Cosa significa la E di ABCDE?","Evoluzione (cambiamento nel tempo)."],["Forma più frequente di melanoma?","Ad accrescimento superficiale."],["Quanti melanomi originano da un nevo?","Circa il 30%."],["Segno di Hutchinson nel melanoma?","Pigmentazione della plica periungueale nel melanoma subungueale."],["Margini della biopsia escissionale?","Stretti, 1-3 mm."]],
mcq:[["Il melanoma con prognosi peggiore per crescita verticale precoce:",["Superficiale","Nodulare","Lentigo maligna melanoma","Nevo di Spitz"],1,"Spesso sfugge all’ABCDE."],["Melanoma della pianta del piede in un paziente africano:",["Lentigo maligna","Acrale lentigginoso","Nodulare sempre","Superficiale"],1,"Più frequente nei fototipi scuri."],["Lo spessore di Breslow si misura:",["In livelli anatomici","In millimetri","In centimetri di diametro","In mitosi"],1,"Dallo strato granuloso."],["Terapia del melanoma metastatico BRAF mutato:",["Solo chirurgia","BRAF + MEK inibitori","Antibiotici","Isotretinoina"],1,"In alternativa immunoterapia."],["Nevo circondato da alone bianco:",["Spitz","Sutton","Reed","Spilus"],1,"Alone acromico."]],
gap:[["Nella regola ABCDE la D indica un diametro superiore a ___ mm.","6",["sei"]],["Il livello di ___ descrive gli strati cutanei invasi.","Clark",[]],["Il melanoma metastatico si tratta con anti-PD-1 come il ___.","nivolumab",["pembrolizumab"]]],
match:[["Breslow","Millimetri"],["Clark","Strati"],["Nodulare","Verticale"],["Acrale","Pianta"],["Sutton","Alone"]],
open:[["Quali sono i fattori di rischio del melanoma?","Fototipo chiaro, ustioni solari soprattutto infantili, esposizione UV intermittente e lampade abbronzanti, numero elevato di nevi o nevi displastici, familiarità, immunodepressione, sindromi genetiche come lo xeroderma pigmentoso.",["fototipo","ustion","lampade","nevi","familiar","immunodep"]],["Come si diagnostica e stadia un melanoma?","Sospetto clinico con ABCDE e brutto anatroccolo, dermatoscopia; biopsia escissionale con margini stretti; istologia con spessore di Breslow, livello di Clark, ulcerazione e mitosi; allargamento dei margini e biopsia del linfonodo sentinella in base al Breslow; stadiazione strumentale.",["ABCDE","dermatoscop","escissional","Breslow","Clark","sentinella"]]],
recap:["Melanoma da cute sana nel 70%.","ABCDE + brutto anatroccolo.","Superficiale il più frequente, nodulare il peggiore.","Breslow = prognosi; biopsia escissionale 1-3 mm.","Metastatico: anti-PD-1, BRAF+MEK.","Prevenzione: fotoprotezione e autoesame."]});

C({id:13,t:"Tumori non melanoma e precancerosi",sub:"Basalioma, spinalioma, cheratosi attinica",
topics:[
["Carcinoma basocellulare",["Neoplasia maligna cutanea più frequente; >40 anni, aree fotoesposte (volto).","Invasività locale, metastasi rarissime.","Varianti: superficiale (chiazza eritematosa con orletto periferico perlaceo), nodulare (nodulo perlaceo con teleangectasie arborizzate), ulcerato (ulcus rodens), pigmentato, sclerodermiforme; forme localmente avanzate.","Terapia: escissione chirurgica (unica opzione nella forma nodulare), chirurgia micrografica di Mohs, crioterapia, imiquimod e terapia fotodinamica nelle superficiali, radioterapia; inibitori di Hedgehog (vismodegib) nelle avanzate."],"Basalioma = PERLA con capillari ad albero, cresce ma non migra."],
["Carcinoma squamocellulare",["Meno frequente del basocellulare ma più del melanoma; può metastatizzare.","Fattori: UV cumulativi, cheratosi attiniche, immunosoppressione (trapiantati), HPV, cicatrici e ulcere croniche, radiazioni, arsenico.","Varianti: superficiale (in situ), nodulare cheratosico, ulcerato, avanzato, delle mucose (labbro, genitali).","Cheratoacantoma: variante a rapida crescita con cratere centrale cheratosico, può regredire.","Diagnosi istologica; terapia chirurgica con margini adeguati, radioterapia, immunoterapia (cemiplimab) nelle forme avanzate."],"Squamocellulare = il fratello che METASTATIZZA."],
["Precancerosi",["Obbligate: cheratosi attinica, cheilite attinica, xeroderma pigmentoso.","Cheratosi attinica: macule-papule ruvide e squamose su cute fotodanneggiata; ‘field cancerization’ (tutta l’area esposta è a rischio).","Xeroderma pigmentoso: difetto genetico di riparazione del DNA, tumori cutanei in età precoce.","Facoltative: malattia di Bowen (carcinoma in situ cutaneo), eritroplasia di Queyrat (in situ del glande), malattia di Paget, papulosi bowenoide (HPV), epidermodisplasia verruciforme, leucoplachia, cheratosi arsenicale, lichen scleroatrofico genitale.","Terapia della cheratosi attinica: crioterapia (lesioni singole), terapia del campo con 5-fluorouracile, imiquimod, diclofenac gel, terapia fotodinamica; fotoprotezione."],"Cheratosi attinica = si SENTE al tatto (carta vetrata) prima di vederla."]
],
fc:[["Tumore maligno cutaneo più frequente?","Carcinoma basocellulare."],["Basalioma: metastatizza?","Raramente: è soprattutto localmente invasivo."],["Precursore principale dello squamocellulare?","Cheratosi attinica."],["Cos’è la malattia di Bowen?","Carcinoma squamocellulare in situ."],["Terapia del campo per cheratosi attiniche?","5-fluorouracile, imiquimod, diclofenac, terapia fotodinamica."]],
mcq:[["Nodulo perlaceo con teleangectasie sul naso:",["Squamocellulare","Basocellulare nodulare","Melanoma","Cheratosi seborroica"],1,"Terapia chirurgica."],["Paziente trapiantato con molte lesioni cheratosiche: tumore più a rischio",["Basocellulare","Squamocellulare","Melanoma","Linfoma"],1,"L’immunosoppressione favorisce lo spinalioma."],["Precancerosi obbligata:",["Malattia di Bowen","Cheratosi attinica","Leucoplachia","Lichen scleroatrofico"],1,"Insieme a cheilite attinica e xeroderma pigmentoso."],["Lesione a crescita rapida con cratere cheratosico che può regredire:",["Cheratoacantoma","Basalioma","Nevo di Spitz","Mollusco"],0,"Variante dello squamocellulare."],["L’eritroplasia di Queyrat interessa:",["Labbro","Glande","Palpebra","Unghia"],1,"Carcinoma in situ."]],
gap:[["Il basalioma ulcerato è detto ulcus ___.","rodens",[]],["Il vismodegib inibisce la via di ___.","Hedgehog",["Sonic Hedgehog"]],["La chirurgia micrografica dei tumori cutanei porta il nome di ___.","Mohs",[]]],
match:[["Basalioma","Perlaceo"],["Spinalioma","Metastasi"],["Cheratosi attinica","Field cancerization"],["Bowen","In situ"],["Xeroderma pigmentoso","Riparazione DNA"]],
open:[["Confronta carcinoma basocellulare e squamocellulare.","Basocellulare: il più frequente, aree fotoesposte, aspetto perlaceo con teleangectasie, invasività locale e metastasi rarissime. Squamocellulare: meno frequente, origina spesso da cheratosi attiniche, favorito da immunosoppressione, HPV e cicatrici croniche, lesioni cheratosiche o ulcerate, può metastatizzare. Entrambi si trattano principalmente con la chirurgia.",["più frequente","perlace","metastas","cheratosi attinic","immunosoppress","chirurg"]],["Distingui precancerosi obbligate e facoltative con esempi.","Obbligate: alto rischio di evoluzione, come cheratosi attinica, cheilite attinica, xeroderma pigmentoso. Facoltative: rischio minore, come malattia di Bowen, eritroplasia di Queyrat, malattia di Paget, papulosi bowenoide, leucoplachia, cheratosi arsenicale, lichen scleroatrofico.",["obbligat","attinic","xeroderma","facoltativ","Bowen","leucoplachia"]]],
recap:["Basocellulare: il più frequente, perlaceo, non metastatizza.","Squamocellulare: da cheratosi attinica, può metastatizzare.","Cheratoacantoma: cratere, può regredire.","Obbligate: cheratosi e cheilite attinica, xeroderma.","Terapia del campo: 5-FU, imiquimod, PDT."]});
